    const snap = snapshot(tab);
    if (snap)
      snapshots.push(snap);
  }
  const attachedTabIds = await ownedDebuggerTabs(targets, (tabId) => chrome.debugger.sendCommand({ tabId }, "Target.getTargetInfo"));
  const versionMatch = /Chrome\/[\d.]+/.exec(navigator.userAgent);
  return {
    t: "hello",
    instanceId: await ensureInstanceId(),
    userAgent: navigator.userAgent,
    browserVersion: versionMatch?.[0] ?? "Chrome/unknown",
    discardedTabsProtocol: 1,
    tabs: snapshots,
    attachedTabIds,
    ownedTabIds: snapshots.filter((snap) => created.has(snap.tabId)).map((snap) => snap.tabId)
  };
}
async function tabWindowId() {
  const windows = await chrome.windows.getAll({ windowTypes: ["normal"] });
  const chosen = windows.find((window) => window.focused) ?? windows.find((window) => window.state !== "minimized") ?? windows[0];
  return chosen?.id;
}
async function runRpc(msg) {
  switch (msg.op) {
    case "attach":
      await chrome.debugger.attach({ tabId: msg.tabId }, "1.3");
      return {};
    case "detach":
      relayInitiatedDetachTabs.add(msg.tabId);
      try {
        await chrome.debugger.detach({ tabId: msg.tabId });
        return {};
      } catch (error) {
        relayInitiatedDetachTabs.delete(msg.tabId);
        throw error;
      }
    case "send":
      return await screenshotCapture.send(msg.sessionId ? { tabId: msg.tabId, sessionId: msg.sessionId } : { tabId: msg.tabId }, msg.method, msg.params);
    case "createTab": {
      const tab = await chrome.tabs.create({ url: msg.url, active: msg.active ?? false, windowId: await tabWindowId() });
      const snap = snapshot(tab);
      if (!snap)
        throw new Error("created tab has no id");
      await markCreatedTab(snap.tabId, true);
      return { tab: snap };
    }
    case "removeTab":
      await chrome.tabs.remove(msg.tabId);
      return {};
    case "activateTab": {
      const tab = await chrome.tabs.get(msg.tabId);
      await chrome.windows.update(tab.windowId, { focused: true });
      await chrome.tabs.update(msg.tabId, { active: true });
      return {};
    }
    case "group":
      return await enqueueGroupOp(() => groupTabs(msg.tabIds, msg.title, msg.color));
    case "ungroup":
      await enqueueGroupOp(() => chrome.tabs.ungroup(msg.tabIds).catch(() => {}));
      return {};
  }
}
function handleRelayMessage(raw) {
  let msg;
  try {
    msg = JSON.parse(raw);
  } catch {
    return;
  }
  if (msg.t === "pong")
    return;
  runRpc(msg).then((result) => post({ t: "rpcResult", id: msg.id, ok: true, result })).catch((err) => {
    post({ t: "rpcResult", id: msg.id, ok: false, error: err instanceof Error ? err.message : String(err) });
  });
}
function scheduleReconnect() {
  if (reconnectTimer !== null)
    return;
  const delay = reconnectDelay;
  reconnectDelay = Math.min(reconnectDelay * 2, RECONNECT_MAX_MS);
  reconnectTimer = setTimeout(() => {
    reconnectTimer = null;
    connect();
  }, delay);
}
async function relayListening(port) {
  try {
    await fetch(`http://127.0.0.1:${port}/json/version`, {
      mode: "no-cors",
      cache: "no-store",
      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS)
    });
    return true;
  } catch {
    return false;
  }
}
async function connect() {
  if (dialing || ws && (ws.readyState === WebSocket.OPEN || ws.readyState === WebSocket.CONNECTING))
    return;
  dialing = true;
  try {
    const settings = await loadSettings();
    if (!await relayListening(settings.port)) {
      scheduleReconnect();
      return;
    }
    const url = `ws://127.0.0.1:${settings.port}/ext${settings.token ? `?token=${encodeURIComponent(settings.token)}` : ""}`;
    const socket = new WebSocket(url);
    ws = socket;
    socket.onopen = () => {
      reconnectDelay = RECONNECT_MIN_MS;
      setBadge(true);
      buildHello().then((hello) => post(hello));
      clearInterval(pingTimer ?? undefined);
      pingTimer = setInterval(() => post({ t: "ping" }), PING_INTERVAL_MS);
    };
    socket.onmessage = (event) => {
      if (typeof event.data === "string")
        handleRelayMessage(event.data);
    };
    socket.onclose = () => {
      if (ws !== socket)
        return;
      ws = null;
      if (pingTimer !== null) {
        clearInterval(pingTimer);
        pingTimer = null;
      }
      setBadge(false);
      enqueueGroupOp(restoreGroups);
      scheduleReconnect();
    };
    socket.onerror = () => {
      socket.close();
    };
  } finally {
    dialing = false;
  }
}
chrome.debugger.onEvent.addListener((source, method, params) => {
  if (source.tabId === undefined)
    return;
  const target = { tabId: source.tabId, sessionId: source.sessionId };
  if (screenshotCapture.handleEvent(target, method, params))
    return;
  if (method === "Target.detachedFromTarget" && typeof params?.sessionId === "string") {
    screenshotCapture.detach({ tabId: source.tabId, sessionId: params.sessionId });
  }
  post({ t: "cdpEvent", tabId: source.tabId, sessionId: source.sessionId, method, params });
});
chrome.debugger.onDetach.addListener((source, reason) => {
  if (source.tabId === undefined)
    return;
  screenshotCapture.detach({ tabId: source.tabId });
  const relayInitiated = relayInitiatedDetachTabs.delete(source.tabId);
  post({ t: "detached", tabId: source.tabId, reason, relayInitiated });
});
chrome.tabs.onCreated.addListener((tab) => {
  const snap = snapshot(tab);
  if (snap)
    post({ t: "tabCreated", tab: snap });
});
chrome.tabs.onUpdated.addListener((_tabId, _changeInfo, tab) => {
  const snap = snapshot(tab);
  if (snap)
    post({ t: "tabUpdated", tab: snap });
});
chrome.tabs.onActivated.addListener(({ tabId }) => {
  chrome.tabs.get(tabId).then((tab) => {
    const snap = snapshot(tab);
    if (snap)
      post({ t: "tabUpdated", tab: snap });
  }).catch(() => {});
});
chrome.tabs.onRemoved.addListener((tabId) => {
  screenshotCapture.detach({ tabId });
  markCreatedTab(tabId, false);
  post({ t: "tabRemoved", tabId });
});
chrome.alarms.create("omp-relay-keepalive", { periodInMinutes: 0.5 });
chrome.alarms.onAlarm.addListener((alarm) => {
  if (alarm.name === "omp-relay-keepalive")
    connect();
});
chrome.storage.onChanged.addListener((_changes, areaName) => {
  if (areaName !== "local")
    return;
  ws?.close();
  connect();
});
chrome.action.onClicked.addListener(() => {
  connect();
  chrome.runtime.openOptionsPage();
});
chrome.runtime.onInstalled.addListener(() => void connect());
chrome.runtime.onStartup.addListener(() => void connect());
connect();

